import { REPLAY_VERSION, type ReplayData } from '../../src/game/replay';
import type { Battle } from '../../src/game/model';
import { attackingWitchBattle } from './attacking-witch';

export function attackingWitchSummonBattle(
  level = 1,
  version = REPLAY_VERSION,
  superTroop = false,
  x = 11.4,
  controlled = true,
) {
  const r = attackingWitchBattle(level, version, x, superTroop),
    kind = superTroop ? 'bigboy' : 'skeleton';
  while (!r.battle.units.some((u) => u.kind === kind)) r.step();
  const unit = r.battle.units.find((u) => u.kind === kind)!;
  if (controlled)
    for (const other of r.battle.units)
      if (other !== unit) (other.native!.effects ??= {}).frozenUntil = 100;
  const untilAttacks = (count: number) => {
    while ((unit.native?.attacks ?? 0) < count) r.step();
  };
  return { ...r, parent: r.unit, unit, untilAttacks };
}

/** Ordinary parent deployment: every body, projectile and summon is generated by real inputs. */
export function attackingWitchSummonRecording(
  level = 1,
  version = REPLAY_VERSION,
  superTroop = false,
  x = 11.4,
) {
  const r = attackingWitchSummonBattle(level, version, superTroop, x, false),
    snapshots: { at: number; battle: Battle }[] = [];
  const snapshot = () => {
    if (snapshots.at(-1)?.at !== r.battle.elapsed)
      snapshots.push({ at: r.battle.elapsed, battle: JSON.parse(JSON.stringify(r.battle)) });
    return r.battle.elapsed;
  };
  const born = snapshot();
  while (!r.unit.attacking) r.step();
  const engaged = snapshot();
  const activeAtEngagement = r.unit.native!.attackWindup?.actionDt ?? 0.05;
  r.untilAttacks(1);
  const first = snapshot();
  r.until(first + 0.2);
  const recovery = snapshot();
  r.untilAttacks(2);
  const second = snapshot();
  r.step();
  r.model.finishBattle();
  return {
    id: r.unit.id,
    parentId: r.parent.id,
    kind: r.unit.kind,
    sourceLevel: r.unit.level!,
    born,
    engaged,
    activeAtEngagement,
    first,
    recovery,
    second,
    snapshots,
    data: JSON.parse(JSON.stringify(r.model.state.raidLog![0].replay!)) as ReplayData,
  };
}
